import{_ as t,o as i,c as n,a2 as a}from"./chunks/framework.Cm6XCzck.js";const p=JSON.parse('{"title":"RCR-20260831 Public Evidence: Runtime Continuity and Admissible Evidence","description":"","frontmatter":{"title":"RCR-20260831 Public Evidence: Runtime Continuity and Admissible Evidence","date":"2026-08-31","column":"research-evidence","category":"evidence","article_type":"evidence-pack","edition":"research-center","summary":"De-identified captured data, a Reader, checkers, and provenance for three Runtime-continuity studies: retry eligibility, cross-session authority and attribution, and time-bounded evidence admissibility.","lifecycle":"Published","publication_authorized":true},"headers":[],"relativePath":"en/research/evidence/2026-08-31-runtime-continuity.md","filePath":"en/research/evidence/2026-08-31-runtime-continuity.md","lastUpdated":1788166937000}'),r={name:"en/research/evidence/2026-08-31-runtime-continuity.md"};function s(o,e,c,d,l,u){return i(),n("div",null,[...e[0]||(e[0]=[a(`<p><a href="/joinwell52/zh/research/evidence/2026-08-31-runtime-continuity">中文</a></p><h1 id="rcr-20260831-runtime-continuity-evidence-package" tabindex="-1">RCR-20260831 | Runtime Continuity Evidence Package <a class="header-anchor" href="#rcr-20260831-runtime-continuity-evidence-package" aria-label="Permalink to &quot;RCR-20260831 | Runtime Continuity Evidence Package&quot;">​</a></h1><p>Status: public review and reproducibility package. All identifiers are synthetic. It contains no real task ledger, credentials, signing keys, or product source.</p><p>This package supports three articles:</p><ol><li><a href="/joinwell52/en/engineering/2026-08-31-audit-failure-retry">Retry eligibility after an audit failure</a></li><li><a href="/joinwell52/en/engineering/2026-08-31-session-principal-continuity">Cross-session authority, execution principal, and attribution</a></li><li><a href="/joinwell52/en/engineering/2026-08-31-audit-evidence-admissibility">Admissible evidence at Runtime decision time</a></li></ol><h2 id="two-recheck-layers" tabindex="-1">Two recheck layers <a class="header-anchor" href="#two-recheck-layers" aria-label="Permalink to &quot;Two recheck layers&quot;">​</a></h2><p><strong>Public captured data and Reader.</strong> Requires Node.js only, with no network or product dependency. It checks article counts, four time cutoffs, and four negative controls.</p><p><strong>Product behavior replay.</strong> Requires authorized access to the fixed CodeFlowMu source and installed dependencies. The probe uses real services but only a local synthetic executor. It does not test real HTTP, Git, issues, payments, or provider-account switching.</p><p>Download the following files into one directory and run:</p><ul><li><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/check.mjs">Checker</a></li><li><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/reader.mjs">Reader</a></li><li><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/check-manifest.mjs">Manifest checker</a></li><li><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/timeline.json">Timeline fixture</a> (the remaining fixtures are in the same directory)</li><li><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/provenance.json">Provenance</a></li><li><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/manifest.json">Manifest</a></li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node check.mjs</span></span>
<span class="line"><span>node check-manifest.mjs</span></span></code></pre></div><p>Expected exit code is 0. The public checker confirms three cross-process recovery controls, eleven authority-consumption cases, eight skill-binding cases, eight Reader cases, and the CatchBench PRE count of 1,187 configurations. These sets must not be added together as a reliability score, detection accuracy, or online benefit.</p><h2 id="claim-→-provenance-→-fixture-→-check" tabindex="-1">Claim → provenance → fixture → check <a class="header-anchor" href="#claim-→-provenance-→-fixture-→-check" aria-label="Permalink to &quot;Claim → provenance → fixture → check&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Evidence</th><th>Supported claim</th><th>Public artifact</th><th>What it proves and does not prove</th></tr></thead><tbody><tr><td>E-A0</td><td>P0–P3 differ by audit-fault location</td><td><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/historical-probes.json">historical probes</a></td><td>P3 preserves a first effect while being written failed; not incident frequency</td></tr><tr><td>E-A1</td><td>New-process recovery depends on dedupe and digest</td><td><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/restart.json">restart</a></td><td>no dedupe 1→2, stable key 1→1, changed digest rejects; not all production executors</td></tr><tr><td>E-B1</td><td>Session change alone does not invalidate matching approval</td><td><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/authorization.json">authorization</a></td><td>eleven conditions and two paths that cannot consume twice; not trusted external identity entry points</td></tr><tr><td>E-B2</td><td>Session binding distinguishes verified, invalid, and sessionless claims</td><td><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/session-binding.json">session binding</a></td><td>2 verified, 5 invalid_claim, 1 not_applicable; public package has no HMAC key</td></tr><tr><td>E-C0</td><td>CatchBench PRE totals and source distribution</td><td><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/catchbench-pre.log">raw output</a></td><td>fixed PRE output and 1,187 configurations; not a fresh model call or CodeFlowMu score</td></tr><tr><td>E-C1</td><td>Proposition, ownership, cutoff, and integrity change admissibility</td><td><a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/fixtures/timeline.json">timeline</a></td><td>Reader executes 4 normal and 4 negative controls; not a product auditor or statistical accuracy</td></tr></tbody></table><h2 id="read-contract-and-limits" tabindex="-1">Read contract and limits <a class="header-anchor" href="#read-contract-and-limits" aria-label="Permalink to &quot;Read contract and limits&quot;">​</a></h2><p>The public Reader fixes a proposition, admits artifacts with the correct owner at or before the cutoff whose content matches the manifest, and then reads the latest allowed effect snapshot. It evaluates admissible evidence rather than every log. <code>unknown</code> is not <code>false</code>; <code>not_observed</code> is not “will never happen.”</p><p>The byte-identical product probe, <a href="/joinwell52/assets/evidence/2026-08-31-runtime-continuity/reproduce-product.mts">reproduce-product.mts</a>, is included but requires source fixed at <code>f0f42f01c8f6d55bfe3d32e108f607841a2900d9</code> and an isolated research output directory.</p><p>The same researcher ran these experiments. There is no independent QA, blind evaluation, production incident frequency, real provider-account escalation result, or online early-warning claim. The manifest detects silent change relative to this package; it is not independent attestation.</p>`,18)])])}const f=t(r,[["render",s]]);export{p as __pageData,f as default};
